INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Public-Domain-Software immer urheberrechtsfrei?', 2, '[{"text": "Ja", "correct": true, "because": "Keine Urheberrechtsansprüche bestehen"}, {"text": "Nein", "correct": false, "because": "Definiert als frei von Rechten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel von Public-Domain-Software?', 3, '[{"text": "Freie Nutzung ermöglichen", "correct": true, "because": "Jeder darf sie verwenden"}, {"text": "Kommerzielle Lizenzierung", "correct": false, "because": "Nicht eingeschränkt"}, {"text": "Manuelle Verteilung", "correct": false, "because": "Frei zugänglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat Public-Domain-Software?', 5, '[{"text": "Keine Nutzungsbeschränkungen", "correct": true, "because": "Frei für alle Zwecke"}, {"text": "Modifizierbarkeit", "correct": true, "because": "Code offen änderbar"}, {"text": "Lizenzpflicht", "correct": false, "because": "Keine Lizenz nötig"}, {"text": "Exklusive Nutzung", "correct": false, "because": "Frei für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Public-Domain-Software kann frei kopiert werden. b) Sie unterliegt immer einer Lizenz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hat keine Lizenzpflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von Public-Domain-Software?', 4, '[{"text": "Quellcode-Verfügbarkeit", "correct": false, "because": "Oft verfügbar"}, {"text": "Verwendungszweck", "correct": false, "because": "Frei wählbar"}, {"text": "Lizenzgebühren", "correct": true, "because": "Keine Gebühren nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Public-Domain-Software kommerziell genutzt werden darf?', 2, '[{"text": "Ja", "correct": true, "because": "Keine Nutzungseinschränkungen"}, {"text": "Nein", "correct": false, "because": "Frei für alle Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkung gibt es bei Public-Domain-Software?', 3, '[{"text": "Keine rechtlichen Einschränkungen", "correct": true, "because": "Vollständig frei"}, {"text": "Lizenzpflicht", "correct": false, "because": "Keine Lizenz nötig"}, {"text": "Manuelle Freigabe", "correct": false, "because": "Automatisch frei"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Software könnte als Public Domain gelten?', 5, '[{"text": "SQLite", "correct": true, "because": "Public Domain erklärt"}, {"text": "Unzip", "correct": true, "because": "Teilweise Public Domain"}, {"text": "Microsoft Office", "correct": false, "because": "Proprietär"}, {"text": "Adobe Photoshop", "correct": false, "because": "Kommerziell lizenziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Public-Domain-Software ist frei modifizierbar. b) Sie ist immer Open Source. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nicht zwingend Open Source"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Public-Domain-Software?', 4, '[{"text": "Verwendungsfreigabe", "correct": false, "because": "Automatisch frei"}, {"text": "Modifikationsrecht", "correct": false, "because": "Inkludiert"}, {"text": "Lizenzvertrag", "correct": true, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Public-Domain-Software dasselbe wie Open-Source-Software?', 2, '[{"text": "Nein", "correct": true, "because": "Open Source hat oft Lizenzbedingungen"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Regeln"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte habe ich bei Public-Domain-Software?', 4, '[{"text": "Kopieren", "correct": true, "because": "Frei erlaubt"}, {"text": "Verändern", "correct": true, "because": "Keine Einschränkungen"}, {"text": "Exklusive Nutzung", "correct": false, "because": "Nicht möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Public-Domain-Software immer sicher ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit nicht garantiert"}, {"text": "Ja", "correct": false, "because": "Prüfung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung von Public-Domain-Software?', 3, '[{"text": "Verwendungszweck prüfen", "correct": true, "because": "Passt zu Anforderungen"}, {"text": "Lizenzgebühren", "correct": false, "because": "Nicht erforderlich"}, {"text": "Manuelle Freigabe", "correct": false, "because": "Automatisch frei"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Public-Domain-Software ist frei verteilbar. b) Sie benötigt immer Quellcode.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Public-Domain-Software?', 5, '[{"text": "Kostenfreiheit", "correct": true, "because": "Keine Lizenzkosten"}, {"text": "Flexibilität", "correct": true, "because": "Frei modifizierbar"}, {"text": "Exklusive Rechte", "correct": false, "because": "Nicht zutreffend"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher vereinfachend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Public-Domain-Software unwichtig?', 3, '[{"text": "Nutzungsfreiheit", "correct": false, "because": "Kernmerkmal"}, {"text": "Verfügbarkeit", "correct": false, "because": "Fördert Zugang"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Softwarefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Public-Domain-Software automatisch Open Source ist?', 2, '[{"text": "Nein", "correct": true, "because": "Open Source hat oft Lizenzbedingungen"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Regeln"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss Public-Domain-Software dokumentiert werden?', 3, '[{"text": "Nein", "correct": true, "because": "Keine rechtliche Pflicht"}, {"text": "Ja", "correct": false, "because": "Freiwillig möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Public-Domain-Software?', 4, '[{"text": "Entwicklung mit SQLite", "correct": true, "because": "SQLite ist Public Domain"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Softwarekontext"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
